const FLOW_PATH = 'u/admin/loan_pipeline'

function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]))
}

function statusPill(j) {
  let label='—', fg='#64748b', bg='#f1f5f9', dot='#94a3b8', pulse=false
  if (j.type === 'QueuedJob') {
    if (j.running) { label='Running'; fg='#1d4ed8'; bg='#eff6ff'; dot='#3b82f6'; pulse=true }
    else { label='Queued'; fg='#a16207'; bg='#fefce8'; dot='#eab308'; pulse=true }
  } else if (j.success === true) { label='Success'; fg='#15803d'; bg='#f0fdf4'; dot='#22c55e' }
  else if (j.success === false) { label='Failed'; fg='#b91c1c'; bg='#fef2f2'; dot='#ef4444' }
  const pulseStyle = pulse
    ? `box-shadow:0 0 0 0 ${dot};animation:dash-pulse 1.4s infinite;`
    : ''
  return `<span style="display:inline-flex;align-items:center;gap:0.3125rem;padding:0.1875rem 0.5rem;background:${bg};color:${fg};border-radius:3px;font-size:0.6875rem;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;">
    <span style="width:0.375rem;height:0.375rem;background:${dot};border-radius:9999px;${pulseStyle}"></span>${label}</span>`
}

function colorize(line) {
  const safe = esc(line)
  if (/\b(ERROR|FAIL|FAILED|Exception|Traceback)\b/i.test(line)) return `<span style="color:#fca5a5;">${safe}</span>`
  if (/\b(WARN|WARNING)\b/i.test(line)) return `<span style="color:#fcd34d;">${safe}</span>`
  if (/\b(SUCCESS|DONE|OK|Completed)\b/i.test(line)) return `<span style="color:#86efac;">${safe}</span>`
  if (/\b(INFO|Running|Started)\b/i.test(line)) return `<span style="color:#93c5fd;">${safe}</span>`
  return `<span style="color:#cbd5e1;">${safe}</span>`
}

function metric(label, value, accent) {
  return `<div style="background:#fff;padding:0.75rem 0.9375rem;border:1px solid #e2e8f0;border-radius:0.375rem;border-top:2px solid ${accent};">
    <div style="font-size:0.65rem;text-transform:uppercase;color:#64748b;letter-spacing:0.08em;font-weight:600;">${esc(label)}</div>
    <div style="font-size:1.5rem;font-weight:600;color:#0f172a;line-height:1.1;margin-top:0.25rem;letter-spacing:-0.02em;font-variant-numeric:tabular-nums;">${value}</div>
  </div>`
}

export async function main() {
  const base = process.env.BASE_INTERNAL_URL || 'http://windmill_server:8000'
  const ws = process.env.WM_WORKSPACE || 'admin'
  const token = process.env.WM_TOKEN || ''
  const auth = { Authorization: `Bearer ${token}` }

  let jobs = [], err = null
  try {
    const r = await fetch(`${base}/api/w/${ws}/jobs/list?script_path_exact=${FLOW_PATH}&per_page=100`, { headers: auth })
    if (!r.ok) err = `${r.status} ${r.statusText}`
    else jobs = await r.json()
  } catch (e) { err = e?.message ?? String(e) }

  const stats = { total: jobs.length, running: 0, success: 0, failed: 0 }
  for (const j of jobs) {
    if (j.type === 'QueuedJob') stats.running++
    else if (j.success === true) stats.success++
    else if (j.success === false) stats.failed++
  }
  const completed = stats.success + stats.failed
  const successRate = completed > 0 ? Math.round((stats.success / completed) * 100) : 0

  // -------- Logs panel: always the most-recent job, with line count + LIVE pulse --------
  let logsBody = `<span style="color:#64748b;">No pipeline runs yet — upload a file to start one.</span>`
  let logsMeta = ''
  let logsCount = ''
  let logsJobId = ''
  let liveDot = ''
  if (jobs.length > 0) {
    const latest = jobs[0]
    const isRunning = latest.type === 'QueuedJob'
    logsJobId = latest.id
    const startedFmt = (latest.started_at || latest.created_at) ? new Date(latest.started_at || latest.created_at).toLocaleTimeString() : '—'

    let lineCount = 0
    try {
      const r = await fetch(`${base}/api/w/${ws}/jobs_u/get_flow_all_logs/${latest.id}`, { headers: auth })
      if (r.ok) {
        const text = await r.text()
        const lines = text.split(/\r?\n/)
        lineCount = lines.length
        if (lineCount === 0 || (lineCount === 1 && lines[0] === '')) {
          logsBody = isRunning
            ? `<span style="color:#94a3b8;">⏳ Waiting for output — job just started…</span>`
            : `<span style="color:#64748b;">(no log output for this job)</span>`
        } else {
          logsBody = lines.slice(-400).map(colorize).join('\n')
        }
      } else {
        logsBody = `<span style="color:#fca5a5;">log fetch failed: ${r.status}</span>`
      }
    } catch (e) { logsBody = `<span style="color:#fca5a5;">${esc(e?.message ?? e)}</span>` }

    logsCount = `<span style="color:#64748b;font-size:0.6875rem;font-variant-numeric:tabular-nums;">${lineCount} lines</span>`
    logsMeta = `<span style="color:#94a3b8;font-family:'JetBrains Mono','Menlo',monospace;font-size:0.6875rem;">${esc(latest.id.slice(0,18))}…</span>
      <span style="color:#64748b;font-size:0.6875rem;">${esc(startedFmt)}</span>
      ${statusPill(latest)}`
    if (isRunning) {
      liveDot = `<span style="display:inline-flex;align-items:center;gap:0.3125rem;padding:0.125rem 0.4375rem;background:#172554;color:#bfdbfe;border-radius:3px;font-size:0.625rem;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;">
        <span style="width:0.375rem;height:0.375rem;background:#3b82f6;border-radius:9999px;box-shadow:0 0 0 0 #3b82f6;animation:dash-pulse 1.4s infinite;"></span>LIVE</span>`
    }
  }

  const tableRows = jobs.slice(0, 30).map(j => {
    const args = j.args || {}
    const started = j.started_at || j.created_at
    const startedStr = started ? new Date(started).toLocaleString() : '—'
    const dur = j.duration_ms != null ? (j.duration_ms/1000).toFixed(2) + 's' : (j.type === 'QueuedJob' && started ? ((Date.now() - new Date(started).getTime())/1000).toFixed(1) + 's…' : '—')
    const file = args.original_filename || (args.file_path||'').split('/').pop() || '—'
    const link = `/run/${j.id}?workspace=${ws}`
    const rowAccent = j.id === logsJobId ? 'background:#fafbfc;' : ''
    return `<tr style="border-top:1px solid #f1f5f9;${rowAccent}">
      <td style="padding:0.4375rem 0.75rem;font-size:0.75rem;color:#334155;white-space:nowrap;">${esc(startedStr)}</td>
      <td style="padding:0.4375rem 0.75rem;font-family:'JetBrains Mono','Menlo',monospace;font-size:0.6875rem;">
        <a href="${link}" target="_blank" rel="noopener" style="color:#1d4ed8;text-decoration:none;">${esc(j.id.slice(0,12))}…</a></td>
      <td style="padding:0.4375rem 0.75rem;font-size:0.75rem;color:#475569;">${esc(j.created_by ?? '—')}</td>
      <td style="padding:0.4375rem 0.75rem;">${statusPill(j)}</td>
      <td style="padding:0.4375rem 0.75rem;font-size:0.75rem;color:#475569;text-align:right;font-variant-numeric:tabular-nums;">${esc(dur)}</td>
      <td style="padding:0.4375rem 0.75rem;font-size:0.75rem;color:#475569;">${esc(file)}</td>
    </tr>`
  }).join('')

  const errBanner = err
    ? `<div style="background:#fef2f2;border:1px solid #fecaca;color:#991b1b;padding:0.5rem 0.75rem;border-radius:0.25rem;font-size:0.75rem;margin-bottom:0.625rem;">Could not load jobs: ${esc(err)}</div>`
    : ''

  return `
    <div data-loan-marker="dashboard" style="display:none;"></div>
    <style>
      @keyframes dash-pulse {
        0%   { box-shadow:0 0 0 0 rgba(59,130,246,0.55); }
        70%  { box-shadow:0 0 0 6px rgba(59,130,246,0); }
        100% { box-shadow:0 0 0 0 rgba(59,130,246,0); }
      }
      #dash-logs { scroll-behavior:smooth; }
    </style>
    ${errBanner}
    <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:0.625rem;margin-bottom:0.875rem;">
      ${metric('Total runs', stats.total, '#0f172a')}
      ${metric('Running', stats.running, '#3b82f6')}
      ${metric('Succeeded', stats.success, '#22c55e')}
      ${metric('Failed', stats.failed, '#ef4444')}
      ${metric('Success rate', successRate + '%', '#0ea5e9')}
    </div>
    <div style="background:#fff;border:1px solid #e2e8f0;border-radius:0.375rem;overflow:hidden;margin-bottom:0.875rem;">
      <div style="padding:0.5rem 0.875rem;background:#f8fafc;border-bottom:1px solid #e2e8f0;display:flex;justify-content:space-between;align-items:center;">
        <div style="display:flex;align-items:center;gap:0.625rem;"><div style="font-size:0.65rem;text-transform:uppercase;color:#64748b;letter-spacing:0.08em;font-weight:600;">Recent runs</div><button onclick="try{recompute('dashboard')}catch(e){}" style="padding:0.0625rem 0.4375rem;background:#fff;color:#475569;border:1px solid #cbd5e1;border-radius:3px;font-size:0.65rem;cursor:pointer;font-weight:600;">↻ refresh</button></div>
        <div style="font-size:0.6875rem;color:#94a3b8;font-variant-numeric:tabular-nums;">${jobs.length} total &middot; showing 30</div>
      </div>
      <div style="max-height:260px;overflow:auto;">
        <table style="width:100%;border-collapse:collapse;">
          <thead style="background:#fafbfc;position:sticky;top:0;z-index:1;">
            <tr>
              <th style="text-align:left;padding:0.375rem 0.75rem;font-size:0.65rem;text-transform:uppercase;color:#64748b;font-weight:600;letter-spacing:0.05em;border-bottom:1px solid #e2e8f0;">Started</th>
              <th style="text-align:left;padding:0.375rem 0.75rem;font-size:0.65rem;text-transform:uppercase;color:#64748b;font-weight:600;letter-spacing:0.05em;border-bottom:1px solid #e2e8f0;">Job ID</th>
              <th style="text-align:left;padding:0.375rem 0.75rem;font-size:0.65rem;text-transform:uppercase;color:#64748b;font-weight:600;letter-spacing:0.05em;border-bottom:1px solid #e2e8f0;">User</th>
              <th style="text-align:left;padding:0.375rem 0.75rem;font-size:0.65rem;text-transform:uppercase;color:#64748b;font-weight:600;letter-spacing:0.05em;border-bottom:1px solid #e2e8f0;">Status</th>
              <th style="text-align:right;padding:0.375rem 0.75rem;font-size:0.65rem;text-transform:uppercase;color:#64748b;font-weight:600;letter-spacing:0.05em;border-bottom:1px solid #e2e8f0;">Duration</th>
              <th style="text-align:left;padding:0.375rem 0.75rem;font-size:0.65rem;text-transform:uppercase;color:#64748b;font-weight:600;letter-spacing:0.05em;border-bottom:1px solid #e2e8f0;">Upload</th>
            </tr>
          </thead>
          <tbody>${tableRows || '<tr><td colspan=\"6\" style=\"padding:1.5rem;text-align:center;color:#94a3b8;font-size:0.8125rem;\">No runs yet</td></tr>'}</tbody>
        </table>
      </div>
    </div>
    <div data-job-id="${logsJobId}" style="border:1px solid #1e293b;border-radius:0.375rem;overflow:hidden;">
      <div style="display:flex;justify-content:space-between;align-items:center;padding:0.4375rem 0.875rem;background:#0f172a;gap:0.75rem;flex-wrap:wrap;">
        <div style="display:flex;align-items:center;gap:0.625rem;">
          <div style="color:#f1f5f9;font-size:0.7rem;font-weight:600;text-transform:uppercase;letter-spacing:0.08em;">Latest run &middot; flow logs</div>
          ${liveDot}
        </div>
        <div style="display:flex;align-items:center;gap:0.75rem;">${logsCount} ${logsMeta}</div>
      </div>
      <pre id="dash-logs" data-job="${logsJobId}" style="margin:0;padding:0.75rem 0.875rem;background:#0b1220;color:#e2e8f0;height:300px;overflow:auto;font-family:'JetBrains Mono','Menlo','Consolas',monospace;font-size:0.7rem;line-height:1.5;white-space:pre-wrap;word-break:break-word;">${logsBody}</pre>
    </div>
    <script>
      (function() {
        const el = document.getElementById('dash-logs')
        if (!el) return
        const jobId = el.getAttribute('data-job')
        const wrapper = el.parentElement
        if (!wrapper) return

        // Initialise on very first render — don't flash for the initial load.
        if (typeof window.__dashLastJob === 'undefined') {
          window.__dashLastJob = jobId
          return
        }

        if (window.__dashLastJob !== jobId && jobId) {
          window.__dashLastJob = jobId
          // Drop a flash banner ABOVE the pre so the user can't miss the transition.
          // Doesn't replace the new logs — sits over them and fades after 2s.
          const old = wrapper.querySelector('.dash-flash')
          if (old) old.remove()
          const flash = document.createElement('div')
          flash.className = 'dash-flash'
          flash.innerHTML = '<span style="display:inline-flex;align-items:center;gap:0.5rem;"><span style="width:0.5rem;height:0.5rem;background:#fff;border-radius:9999px;box-shadow:0 0 0 0 #fff;animation:dash-pulse 1.4s infinite;"></span>NEW RUN STARTED</span><span style="margin-left:0.75rem;opacity:0.7;font-family:monospace;font-size:0.65rem;">' + jobId.slice(0,18) + '\u2026</span>'
          flash.style.cssText = 'position:absolute;top:0;left:0;right:0;background:#1d4ed8;color:#fff;text-align:center;padding:0.5rem 0.75rem;font-size:0.7rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;z-index:2;box-shadow:0 2px 8px rgba(0,0,0,0.25);transition:opacity 0.4s,transform 0.4s;'
          wrapper.style.position = 'relative'
          wrapper.appendChild(flash)
          setTimeout(() => { flash.style.opacity = '0'; flash.style.transform = 'translateY(-100%)' }, 1600)
          setTimeout(() => flash.remove(), 2200)
          el.scrollTop = 0
        } else {
          // Same job, just got more logs — tail-follow.
          el.scrollTop = el.scrollHeight
        }
      })()
    </script>
  `
}

if (window.__dashPoll) clearInterval(window.__dashPoll)
window.__dashPoll = setInterval(() => { try { recompute('dashboard') } catch (_) {} }, 1000)
return { polling_started_at: new Date().toISOString(), interval_ms: 1000 }
